import { ProductModel } from "./models/product";

export async function listProducts(categoryId: string) {
  return ProductModel.find({ categoryId, active: true })
    .select({ name: 1, priceCents: 1 })
    .sort({ name: 1 })
    .limit(50)
    .lean()
    .exec();
}
